R=pathlib.Path('.');D='2026-10-21';NOW=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat()
def load(p):return json.loads((R/p).read_text(encoding='utf-8-sig'))
def save(p,x):
 p=R/p;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
