def t(a,b):
 over[a]=b
 if a.startswith(('## ','### ')):over[a.lstrip('# ')]=b.lstrip('# ')
 return a
def photo(k,zh,en):
 p=photos[k];return dict(image='/'+p['file'].removeprefix('public/'),imageAlt=t(zh,en),imageCredit=p['author']+' / '+p['license']+'; cropped',imageSource=p['source'],imageLicense=p['license'])
def md(path,fm,pairs,key):
 p=R/path;assert not p.exists(),path
 p.write_text('---\n'+''.join(k+': '+json.dumps(v,ensure_ascii=False)+'\n' for k,v in fm.items())+'---\n\n'+'\n\n'.join(t(a,b) for a,b in pairs)+f'\n\n[Photo attribution and adaptation license](/images/daily/{D}/credits.html#{key})\n',encoding='utf-8')
 for suf,eng in [('｜環球教育新聞網 Global Education News',' | Global Education News'),('｜台灣國際獎學金雷達',' | Taiwan Global Scholarship Radar')]:over[fm['title']+suf]=over[fm['title']]+eng
