 path='src/pages/scholarships/items/'+slug+'.md';md(path,fm,[('## 補助與門檻','## Value and threshold'),(qual,qe),(ex,ee)]+common+[(f'[完整獎學金條款]({terms})',f'[Full scholarship terms]({terms})')],key)
