diySources=[dict(label='Flinders | current academic scholarships',url=U['flinders']),dict(label='StudyU | independent institution and course guide',url=U['flinders-second'])]
md('src/pages/study-abroad/'+diySlug+'.md',dict(layout='../../layouts/ArticleLayout.astro',title=t(diyTitle,'Flinders DIY: check your course before comparing 20%, 25% and 30% awards'),description=t('以Adelaide的Flinders為例，分開校區、課程排除、成績換算與實際付款，建立可執行的申請清單。','Plan a Flinders application by checking campus, excluded courses, grade equivalence and payment timing.'),date=NOW,author='LTU Global Education News 編輯部',category=t('留學DIY導航','Study abroad DIY'),topic='australia',tags=['Flinders','Adelaide','2027'],**photo('flinders-diy','Flinders主校區山坡視角資料照','Archive hillside view of the Flinders main campus'),sources=diySources),[
('## 從課程出發','## Start with the course'),('Flinders在Adelaide提供不同校區與課程。編輯建議：先列出課程名稱、授課地點、入學條件與實際修業時間，再找住宿；不要把城市校區與Bedford Park當成同一個通勤位置。本文是選校規劃指南，沒有虛構學生故事。','Flinders offers courses across different Adelaide locations. Editorial guidance: confirm the programme, teaching site, entry requirements and duration before choosing housing. City and Bedford Park are different commuting destinations. This is a planning guide, not an invented student story.'),
('## 獎助分方案比較','## Compare awards separately'),('三個方案的學費減免比例與門檻不同，不能直接相加。請校方換算台灣成績，不把ATAR當作台灣百分制；專業認證課程尤其要查排除清單。StudyU的獨立指南亦提醒各方案有課程限制。','The three awards have different rates and thresholds and cannot simply be added together. Ask Flinders to assess Taiwanese qualifications; ATAR is not a Taiwanese percentage. Check exclusions, especially for professional programmes, as the separate StudyU guide also advises.'),
('## 取得offer後再改預算','## Budget from the offer'),('編輯建議：同時保存有獎與無獎兩份預算，另列生活費、保險、交通及押金。確認獎助寫入offer，核對接受與付款日期及續領義務，再決定可負擔範圍。','Editorial guidance: keep funded and unfunded budgets, with living costs, insurance, transport and deposits listed separately. Confirm the award in the offer, acceptance/payment dates and continuing obligations before deciding affordability.')],'flinders-diy')
peterSlug='canada-sop-study-plan-program-fit-2026';pt='加拿大SOP怎麼寫？Peter提醒先把經驗連回學程要求';pe='Writing a Canadian SOP: Peter links real experience to programme requirements'
pb=[('### 先確認學程是否要求','### Check the programme first'),('Peter最新貼文提醒，SOP不是每個加拿大大學部課程的統一要求。卡加利大學官方申請指引也明確要求逐一核對學程文件；文件名稱與格式不能跨校照搬。','Peter’s latest post cautions that an SOP is not a universal requirement for Canadian undergraduate programmes. Calgary’s official guide likewise asks applicants to check programme-specific documents. Names and formats should not be transferred unchanged between institutions.'),('### 用真實經驗說明準備','### Demonstrate preparation through real experience'),('Peter建議先整理選擇學程的原因、已完成的準備與未來方向。UBC電腦科學的Statement of Intent指引，也要求說明研究興趣、學術或職涯規劃及相關經驗。這是該學程的例子，不能推成所有學校一律相同。','Peter recommends connecting programme choice, preparation and future direction. UBC Computer Science’s statement guidance similarly asks about research interests, academic/career plans and relevant experience. That is a programme example, not a universal rule.'),('### 寫作前的實用整理','### A practical preparation exercise'),('先列出一項確實做過的課程或專題，說明自己的角色、遇到的問題與學到的能力，再對照目標學程的真實資源。不要虛構實習、研究或教授承諾；未確定的機會寫成希望爭取的目標。原文的示例不是學生真實案例。','Choose a real course or project, explain your role, a problem and what you learned, then connect it to verified programme resources. Do not invent internships, research or supervisor commitments. Describe uncertain opportunities as goals. The original examples are illustrative, not documented student cases.')]
pa=dict(slug=peterSlug,title=t(pt,pe),description=t('以UBC與卡加利官方文件交叉查核，保留Peter對申請動機與準備的核心建議。','A verified adaptation of Peter’s advice, checked against UBC and Calgary application guidance.'),topic=t('加拿大升學申請','Canadian applications'),author='Peter',importedAt=D,originalPublishedAt=None,originalDateLabel=t('7小時前','7 hours ago'),originalDatePrecision='relative',dateObservedAt=D,sourceUrl=U['peter'],sourceId='pfbid0W2tnnXQphL7wtMfMMqu69qBcti4ACJJARs49Jg6dXGAoJnNDZ1ptUuosyggtMaC6l',edition='verified-edit',**photo('peter','UBC工程學生中心室內資料照','Archive interior of UBC’s Engineering Student Centre'),imageCaption=t('授權校園資料照，非原貼文AI圖卡；照片授權見來源。','Licensed campus archive photograph, not the original AI card; see source for the licence.'),imageRights='CC BY-SA 4.0',note=t('本篇為查核整理版，沒有把SOP當成全部課程的共同要求；未納入原文的簽證細節。','Verified adaptation; an SOP is not treated as universal, and visa details from the original are omitted.'),body=[t(a,b) for a,b in pb],sources=[['Peter | original post',U['peter']],['UBC | Computer Science statement',U['ubc']],['University of Calgary | programme-specific documents',U['calgary']],['Wikimedia Commons | licensed campus photograph',photos['peter']['source']]])
